import{_ as i,c as n,o as a,aj as r}from"./chunks/framework.CSCBGoZg.js";const g=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"reference/plugin-overview.md","filePath":"reference/plugin-overview.md","lastUpdated":0}'),t={name:"reference/plugin-overview.md"};function o(s,e,l,d,p,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to “Plugins”">​</a></h1><p>Plugins are the main interface for adding features to Reeve and integrating Reeve with other software. They can be used to:</p><ul><li>discover and trigger pipelines from various environments.</li><li>provide environment variables and secrets to pipelines.</li><li>react to the status of running pipelines.</li><li>enrich the CLI and web interface with custom features.</li></ul><h2 id="adding-plugins" tabindex="-1">Adding plugins <a class="header-anchor" href="#adding-plugins" aria-label="Permalink to “Adding plugins”">​</a></h2><p>Add plugins to the Reeve server plugin directory (<code>/etc/reeve/plugins</code>) and restart the server after configuration.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>Configuration for each plugin is provided as environment variables to the Reeve server. Each plugin uses its own prefix <code>REEVE_PLUGIN_&lt;plugin name&gt;_</code>. If you want to specify a setting for all available plugins, use the <code>REEVE_SHARED_</code> prefix instead.</p>',7)])])}const f=i(t,[["render",o]]);export{g as __pageData,f as default};
